using System.Linq;
using AiLabs.Rules.Config;
using AiLabs.Rules.Core;
using AiLabs.Rules.Sim;
using AiLabs.Rules.State;
using AiLabs.Rules.Systems;
using AiLabs.SimTests.Support;
using Xunit;

namespace AiLabs.SimTests;

/// <summary>Q1046–Q1115: batch 20 wind-down — rivals/chips series (schema 31).</summary>
public class HatchRivalsChipsWinddownLaterTests
{
    static ModelState M(Game g, int c) => new ModelState { Id = g.State.TakeId(), LineId = "mini", Capability = c, Status = ModelStatus.Released, Alignment = 500, Name = "W" };
    static void Acq(Game g, LabState r) { r.Models.Add(M(g, 507)); r.Cash = -16_050; r.WeeksInDebt = 1; Finance.Earn(g.Me, LedgerLine.CapitalIn, 86_000_000); g.Do(Command.AcquireLab(g.Id, r.Id)); }

    [Fact] public void Q1046_winddown_1046() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4200, 8)); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 54_000_000); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); Acq(g, r); Assert.Equal(31, g.State.Schema); }
    [Fact] public void Q1047_winddown_1047() { var g = Game.New(seed: 1801); var r = g.Rival("openaye"); r.Models.Add(M(g, 522)); r.Cash = -16_700; Finance.Earn(g.Me, LedgerLine.CapitalIn, 71_000_000); g.Do(Command.AcquireLab(g.Id, r.Id)); g.Refused(Command.QueueGpuPurchase(r.Id, 1, HardwareBatch.Hq), CommandError.LabAbsorbed); }
    [Fact] public void Q1048_winddown_1048() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4500, 6)); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 44_000_000); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); Acq(g, r); SaveSchemaPretend.AssertRoundTrip(g.Sim); }
    [Fact] public void Q1049_winddown_1049() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4000, 8)); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 52_000_000); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 2)); Acq(g, r); Assert.True(LabQueries.ParticipatesInEconomy(g.Me)); }
    [Fact] public void Q1050_winddown_1050() { var g = Game.New(seed: 1804); var r = g.Rival("openaye"); r.Models.Add(M(g, 538)); r.Cash = -17_400; Finance.Earn(g.Me, LedgerLine.CapitalIn, 80_000_000); g.Do(Command.AcquireLab(g.Id, r.Id)); Assert.Contains(g.State.Events, e => e.Kind == EventKind.LabAcquired); }
